<?php
require_once __DIR__ . '/../conexion.php';
$r=$conexion->query("SELECT a.matricula_al,CONCAT(a.nombre_al,' ',a.apaterno_al,' ',a.amaterno_al) AS alumno,m.descripcion_mat,am.calificacion FROM asignar_materia am INNER JOIN alumnos a ON am.idalumn=a.idalumn INNER JOIN materias m ON am.idmateria=m.idmateria ORDER BY a.nombre_al,m.descripcion_mat");
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Boletas</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../assets/estilos.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><a href="../index.php" class="btn btn-secondary mb-3 d-print-none">Volver al menú</a><h2>Boletas</h2><div class="table-responsive"><table class="table table-bordered table-striped"><thead class="table-dark"><tr><th>Matrícula</th><th>Alumno</th><th>Materia</th><th>Calificación</th></tr></thead><tbody><?php while($f=$r->fetch_assoc()):?><tr><td><?php echo htmlspecialchars($f['matricula_al']);?></td><td><?php echo htmlspecialchars($f['alumno']);?></td><td><?php echo htmlspecialchars($f['descripcion_mat']);?></td><td><?php echo $f['calificacion']===null?'Sin capturar':htmlspecialchars($f['calificacion']);?></td></tr><?php endwhile;?></tbody></table></div><button onclick="print()" class="btn btn-primary d-print-none">Imprimir</button></main></body></html>
